import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"长恨歌","description":"","frontmatter":{"title":"长恨歌","date":"2026-11-23T00:00:00.000Z","seq":2,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"白居易","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/长恨歌.md","filePath":"blogs/唐诗三百首·七言古诗/长恨歌.md"}'),o={name:"blogs/唐诗三百首·七言古诗/长恨歌.md"};function l(c,a,n,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="长恨歌" tabindex="-1">长恨歌 <a class="header-anchor" href="#长恨歌" aria-label="Permalink to &quot;长恨歌&quot;">​</a></h1><p class="poem-meta">唐 · 白居易　·　七言古诗</p><div class="poem"><p class="poem-stanza">汉皇重色思倾国，御宇多年求不得。杨家有女初长成，养在深闺人未识。</p><p class="poem-stanza">天生丽质难自弃，一朝选在君王侧。回眸一笑百媚生，六宫粉黛无颜色。</p><p class="poem-stanza">春寒赐浴华清池，温泉水滑洗凝脂。侍儿扶起娇无力，始是新承恩泽时。</p><p class="poem-stanza">云鬓花颜金步摇，芙蓉帐暖度春宵。春宵苦短日高起，从此君王不早朝。</p><p class="poem-stanza">承欢侍宴无闲暇，春从春游夜专夜。后宫佳丽三千人，三千宠爱在一身。</p><p class="poem-stanza">金屋妆成娇侍夜，玉楼宴罢醉和春。姊妹弟兄皆列土，可怜光彩生门户。</p><p class="poem-stanza">遂令天下父母心，不重生男重生女。骊宫高处入青云，仙乐风飘处处闻。</p><p class="poem-stanza">缓歌慢舞凝丝竹，尽日君王看不足。渔阳鼙鼓动地来，惊破霓裳羽衣曲。</p><p class="poem-stanza">九重城阙烟尘生，千乘万骑西南行。翠华摇摇行复止，西出都门百余里。</p><p class="poem-stanza">六军不发无奈何，宛转蛾眉马前死。花钿委地无人收，翠翘金雀玉搔头。</p><p class="poem-stanza">君王掩面救不得，回看血泪相和流。黄埃散漫风萧索，云栈萦纡登剑阁。</p><p class="poem-stanza">峨嵋山下少人行，旌旗无光日色薄。蜀江水碧蜀山青，圣主朝朝暮暮情。</p><p class="poem-stanza">行宫见月伤心色，夜雨闻铃肠断声。天旋地转回龙驭，到此踌躇不能去。</p><p class="poem-stanza">马嵬坡下泥土中，不见玉颜空死处。君臣相顾尽沾衣，东望都门信马归。</p><p class="poem-stanza">归来池苑皆依旧，太液芙蓉未央柳。芙蓉如面柳如眉，对此如何不泪垂。</p><p class="poem-stanza">春风桃李花开日，秋雨梧桐叶落时。西宫南内多秋草，落叶满阶红不扫。(花开日 一作：花开夜；南内 一作：南苑)</p><p class="poem-stanza">梨园弟子白发新，椒房阿监青娥老。夕殿萤飞思悄然，孤灯挑尽未成眠。</p><p class="poem-stanza">迟迟钟鼓初长夜，耿耿星河欲曙天。鸳鸯瓦冷霜华重，翡翠衾寒谁与共。</p><p class="poem-stanza">悠悠生死别经年，魂魄不曾来入梦。临邛道士鸿都客，能以精诚致魂魄。</p><p class="poem-stanza">为感君王辗转思，遂教方士殷勤觅。排空驭气奔如电，升天入地求之遍。</p><p class="poem-stanza">上穷碧落下黄泉，两处茫茫皆不见。忽闻海上有仙山，山在虚无缥渺间。</p><p class="poem-stanza">楼阁玲珑五云起，其中绰约多仙子。中有一人字太真，雪肤花貌参差是。</p><p class="poem-stanza">金阙西厢叩玉扃，转教小玉报双成。闻道汉家天子使，九华帐里梦魂惊。</p><p class="poem-stanza">揽衣推枕起徘徊，珠箔银屏迤逦开。云鬓半偏新睡觉，花冠不整下堂来。</p><p class="poem-stanza">风吹仙袂飘飘举，犹似霓裳羽衣舞。玉容寂寞泪阑干，梨花一枝春带雨。(阑 通：栏；飘飘 一作：飘飖)</p><p class="poem-stanza">含情凝睇谢君王，一别音容两渺茫。昭阳殿里恩爱绝，蓬莱宫中日月长。</p><p class="poem-stanza">回头下望人寰处，不见长安见尘雾。惟将旧物表深情，钿合金钗寄将去。</p><p class="poem-stanza">钗留一股合一扇，钗擘黄金合分钿。但教心似金钿坚，天上人间会相见。</p><p class="poem-stanza">临别殷勤重寄词，词中有誓两心知。七月七日长生殿，夜半无人私语时。</p><p class="poem-stanza">在天愿作比翼鸟，在地愿为连理枝。天长地久有时尽，此恨绵绵无绝期。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
